/* ==========================================================================
   >>> EDIT THESE FOUR VALUES, THEN NEVER AGAIN <<<
   ========================================================================== */
const CALENDAR_ID = 'primary';                       // or the dentist's calendar id
const SHEET_ID    = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';    // from the sheet URL
const PUBLIC_BASE = 'https://condone-making-amount.ngrok-free.dev';         // URL patients' email links hit
const CLINIC_NAME = 'Smile Dental Clinic';
const CLINIC_WHATSAPP = '15551915007';   // the clinic's WhatsApp number, digits only with country code, e.g. 923001234567.
                               // Email buttons open this chat with the message ready. '' = buttons work as before.
/* ========================================================================== */

const b = $input.first().json.body || {};

// notify:'none' skips the confirm-link email. Workflow 11 uses it for WhatsApp
// bookings, which are confirmed in the chat instead. Accepting it from anyone
// is safe: anyone can already place a hold with a throwaway email address, and
// the WhatsApp confirmation itself lives behind the internal key in workflow 11.
const notify = String(b.notify || '').toLowerCase() === 'none' ? 'none' : 'email';
const source = /^[a-z]{2,20}$/.test(String(b.source || '')) ? String(b.source) : 'web';
// A doctor_id from the Doctors tab, or "any" to give the patient whoever is free.
const doctor = String(b.doctor || 'any').trim().toLowerCase() || 'any';

for (const k of ['service','date','time','name','phone'])
  if (!b[k]) throw new Error('Missing field: ' + k);
if (!/^\d{4}-\d{2}-\d{2}$/.test(b.date))  throw new Error('Bad date');
if (!/^\d{2}:\d{2}$/.test(b.time))        throw new Error('Bad time');
// The website confirms by email, so there it is required. On WhatsApp the
// patient confirms in the chat; an email is welcome for reminders, not required.
const email = String(b.email || '').trim();
if (!email && notify !== 'none') throw new Error('Missing field: email');
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) throw new Error('Bad email');

// These are typed by a stranger and written into the clinic's sheet. Google
// Sheets runs any cell that starts with = + - or @ as a formula, so those
// characters are removed from the start. A phone keeps only what a phone has.
const plain = v => String(v ?? '').replace(/^[\s=+\-@]+/, '').trim();
const name  = plain(b.name).slice(0, 120);
const notes = plain(b.notes).slice(0, 1000);
const phone = String(b.phone).replace(/[^\d+\-() ]/g, '').replace(/^[\s\-()]+/, '').trim();
if (!name)  throw new Error('Missing field: name');
if (phone.replace(/\D/g, '').length < 7) throw new Error('Bad phone');
if (email && /^[=+\-@]/.test(email)) throw new Error('Bad email');

// Six digits, not four: with four, two patients share a reference after about
// a hundred bookings, and every lookup by reference starts to hit the wrong row.
const ref   = 'DN-' + Math.floor(100000 + Math.random() * 900000);
const token = [...Array(32)].map(() => Math.floor(Math.random()*36).toString(36)).join('');
const base  = new Date(b.date + 'T00:00:00Z');
const iso   = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z');

return [{ json: { ...b, name, notes, phone, email, notify, source, doctor, CALENDAR_ID, SHEET_ID, PUBLIC_BASE, CLINIC_NAME, CLINIC_WHATSAPP, ref, token,
  timeMin: iso(new Date(base.getTime() - 86400000)),
  timeMax: iso(new Date(base.getTime() + 2 * 86400000)) } }];

// ===== DentalFlow availability rules =========================================
// The SAME code sits in workflow 01 (which times to offer) and workflow 02
// (re-check at the moment of booking), so the two can never disagree.
//
// Doctors tab:  doctor_id | name | calendar_id | services | email | active
//   services:   comma-separated service ids, or blank / "all"
// Hours tab:    day | open | close | break_start | break_end | closed | doctor
//   A doctor with ANY rows of their own uses only those rows: a day with no
//   row is a day off. A doctor with no rows uses the clinic rows (doctor blank).
// Nobody active in the Doctors tab: one doctor on the clinic calendar, exactly
// as before multi-doctor support. (The tab itself must exist: run the sheet
// upgrade before importing these workflows.)
const DF = (() => {
  const clean = v => String(v ?? '').trim();
  // "14:00", "14:00:00", "14.00" and "2:00 PM" all mean the same time; a sheet may show any of them.
  const toMin = t => {
    const m = /^(\d{1,2})[:.](\d{2})(?::\d{2})?\s*([ap])?\.?m?\.?$/i.exec(clean(t));
    if (!m) return NaN;
    let h = Number(m[1]); const ap = (m[3] || '').toLowerCase();
    if (ap === 'p' && h < 12) h += 12;
    if (ap === 'a' && h === 12) h = 0;
    return h * 60 + Number(m[2]);
  };
  const toHHMM = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  const truthy = v => clean(v).toUpperCase() === 'TRUE';
  const parts = (isoStr, tz) => {
    const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit',
      day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
    const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
    return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
  };
  const dayName = (date, tz) => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long' })
    .format(new Date(date + 'T12:00:00Z')).toLowerCase();

  function settings(rows) { const s = {}; for (const r of rows || []) s[clean(r[0])] = r[1]; return s; }

  function services(rows) {
    return (rows || []).map(r => ({ id: clean(r[0]), name: clean(r[1]), min: Number(r[2]), price: Number(r[3]),
      active: r[4] === undefined || clean(r[4]).toUpperCase() !== 'FALSE' })).filter(s => s.id);
  }

  function doctors(rows, fallbackCalendar, fallbackName) {
    const list = (rows || []).map(r => ({
      id: clean(r[0]).toLowerCase(), name: clean(r[1]) || clean(r[0]), calendarId: clean(r[2]),
      services: clean(r[3]), email: clean(r[4]),
      active: r[5] === undefined || clean(r[5]).toUpperCase() !== 'FALSE'
    })).filter(d => d.id && d.calendarId && d.active);
    if (list.length) return list;
    return [{ id: 'clinic', name: fallbackName || 'the dentist', calendarId: fallbackCalendar || 'primary',
              services: 'all', email: '', active: true, implicit: true }];
  }

  const doesService = (d, svcId) => {
    const s = d.services.toLowerCase();
    return !s || s === 'all' || s.split(/[\s,;]+/).filter(Boolean).includes(String(svcId).toLowerCase());
  };

  // wanted: a doctor id, or '' / 'any' for every doctor who does this treatment
  function eligible(docs, svcId, wanted) {
    const w = clean(wanted).toLowerCase();
    const any = !w || w === 'any';
    return docs.filter(d => doesService(d, svcId) && (any || d.id === w));
  }

  function hoursFor(hoursRows, doctorId, dow) {
    const rows = hoursRows || [];
    const own = rows.filter(r => clean(r[6]).toLowerCase() === doctorId);
    const pool = own.length ? own : rows.filter(r => !clean(r[6]));
    const r = pool.find(x => clean(x[0]).toLowerCase() === dow);
    if (!r || truthy(r[5])) return null;                          // no row or closed = not working
    const open = toMin(r[1] || '10:00'), close = toMin(r[2] || '20:00');
    if (!(close > open)) return null;
    const bs = toMin(r[3]), be = toMin(r[4]);
    return { open, close, brk: bs < be ? [bs, be] : null };
  }

  // Busy blocks for one calendar on one day, in minutes. A calendar Google
  // could not read is treated as fully busy: an unreadable diary must never
  // look empty, or that doctor would be double-booked.
  // Google may answer for "primary" under the account's email address instead.
  // `asked` is every calendar id we asked about: one answer under a key we did
  // not ask for can only be that calendar.
  function busyFor(fb, calId, day, tz, asked) {
    const cal = (fb && fb.calendars) || {};
    let entry = cal[calId];
    if (!entry) {
      const keys = Object.keys(cal);
      const spare = asked ? keys.filter(k => !asked.includes(k)) : keys;
      if (spare.length === 1 && (asked || keys.length === 1)) entry = cal[spare[0]];
    }
    if (!entry || (entry.errors && entry.errors.length)) return { ok: false, blocks: [[0, 1440]] };
    const blocks = [];
    for (const b of entry.busy || []) {
      const s = parts(b.start, tz), e = parts(b.end, tz);
      if (e.date < day || s.date > day) continue;
      blocks.push([s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min]);
    }
    return { ok: true, blocks };
  }

  // Does an appointment of `dur` minutes at `start` fit this doctor's day?
  function fits(start, dur, buffer, h, blocks) {
    if (!h || !(start >= h.open) || start + dur > h.close) return false;
    const all = h.brk ? blocks.concat([h.brk]) : blocks;
    return !all.some(([bs, be]) => start < be && (start + dur + buffer) > bs);
  }

  function freeTimes({ dur, buffer, gran, earliest, h, blocks }) {
    const out = [];
    if (!h) return out;
    for (let t = h.open; t + dur <= h.close; t += gran) {
      if (t < earliest) continue;
      if (fits(t, dur, buffer, h, blocks)) out.push(toHHMM(t));
    }
    return out;
  }

  const busyMinutes = blocks => blocks.reduce((n, [a, b]) => n + Math.max(0, b - a), 0);

  return { clean, toMin, toHHMM, parts, dayName, settings, services, doctors, doesService,
           eligible, hoursFor, busyFor, fits, freeTimes, busyMinutes };
})();
// =============================================================================

const prettyDate = (d, tz) => new Date(d + 'T12:00:00Z')
  .toLocaleDateString('en-GB', { timeZone: tz, weekday:'long', day:'numeric', month:'long', year:'numeric' });
const pretty12 = t => { const [h,m] = String(t).split(':').map(Number);
  return `${((h+11)%12)+1}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`; };

const v  = $('Validate Request').first().json;
const vr = $('Read Clinic Config').first().json.valueRanges || [];
const w  = $('Which Doctors').first().json;
const fb = $input.first().json;
const rows = i => (vr[i] && vr[i].values) || [];

const svc = DF.services(rows(0)).find(s => s.id === v.service);
if (!svc) throw new Error('Unknown service: ' + v.service);

const set      = DF.settings(rows(2));
const TZ       = set.timezone || 'Asia/Karachi';
const BUFFER   = Number(set.buffer_min   ?? 10);
const HOLD     = Number(set.hold_minutes ?? 30);
const holidays = new Set(rows(3).map(r => DF.clean(r[0])));

const start = DF.toMin(v.time);
const LEAD_H = Number(set.lead_hours ?? 2);
// The slot list is built for the treatment's normal length. A first visit gets
// 10 extra minutes when they fit; when they don't, the patient still gets the
// time they were offered rather than a "slot taken" for a slot that is free.
const plain = svc.min, padded = svc.min + (v.firstVisit ? 10 : 0);
const dow   = DF.dayName(v.date, TZ);
const nowP  = DF.parts(new Date().toISOString(), TZ);

/* ---- THE RE-CHECK, per doctor ------------------------------------------
   The patient's slot list may be minutes old. Each candidate doctor must be
   working at that time, readable in Google Calendar, and free (plus buffer).
   For "any", the least busy doctor that day gets the patient, which spreads
   bookings evenly; a tie goes to whoever is listed first in the Doctors tab. */
let chosen = null, reason = 'slot-taken', dur = plain;
// Same lead time as the slot list, less 30 minutes for the time it takes to fill in the form.
const tooSoon = v.date === nowP.date && start < nowP.min + LEAD_H * 60 - 30;
if (holidays.has(v.date)) reason = 'holiday';
else if (v.date < nowP.date || (v.date === nowP.date && start <= nowP.min)) reason = 'past';
else if (tooSoon) reason = 'too-soon';
else if (!w.eligible.length) reason = 'no-doctor';
else {
  const asked = w.eligible.map(x => x.calendarId);
  const cands = w.eligible.map((d, i) => ({ d, i, h: DF.hoursFor(rows(1), d.id, dow),
    busy: DF.busyFor(fb, d.calendarId, v.date, TZ, asked) })).filter(x => x.h && x.busy.ok);
  const order = (a, b) => DF.busyMinutes(a.busy.blocks) - DF.busyMinutes(b.busy.blocks) || a.i - b.i;
  for (const len of padded > plain ? [padded, plain] : [plain]) {
    const fit = cands.filter(x => DF.fits(start, len, BUFFER, x.h, x.busy.blocks)).sort(order);
    if (fit.length) { chosen = fit[0].d; dur = len; break; }
  }
}
const free = !!chosen;
const doctorId   = chosen && !chosen.implicit ? chosen.id   : '';
const doctorName = chosen && !chosen.implicit ? chosen.name : '';
const calendarId = chosen ? chosen.calendarId : '';

const expiresAt = new Date(Date.now() + HOLD * 60000).toISOString();
const event = !chosen ? null : {
  summary: `[PENDING] ${v.name} — ${svc.name}`,
  description: [
    `Reference: ${v.ref}`, `Patient: ${v.name}`, `Phone: ${v.phone}`, `Email: ${v.email || '—'}`,
    ...(doctorName ? [`Dentist: ${doctorName}`] : []),
    `First visit: ${v.firstVisit ? 'Yes' : 'No'}`, `Notes: ${v.notes || '—'}`, '',
    'STATUS: awaiting patient confirmation.',
    'This hold is released automatically if the patient does not confirm.'
  ].join('\n'),
  start: { dateTime: `${v.date}T${DF.toHHMM(start)}:00`, timeZone: TZ },
  end:   { dateTime: `${v.date}T${DF.toHHMM(start + dur)}:00`, timeZone: TZ },
  colorId: '6',
  extendedProperties: { private: { ref: v.ref, token: v.token, status: 'PENDING',
    expiresAt, phone: v.phone, email: v.email, serviceId: svc.id, doctor: doctorId } }
};

return [{ json: { ...v, free, reason: free ? 'ok' : reason, event, timezone: TZ, holdMinutes: HOLD,
  doctorId, doctorName, calendarId,
  serviceName: svc.name, price: svc.price, durationMin: dur, expiresAt,
  prettyDate: prettyDate(v.date, TZ), prettyTime: pretty12(v.time) } }];

// The name comes from a public form: escape it so it cannot inject HTML into the clinic's email.
const esc = s => String(s || '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const c  = $('Check Availability').first().json;
const ev = $('Create PENDING Hold').first().json;               // the created Google Calendar event
// Buttons open the clinic's WhatsApp chat with the message already typed; the patient just presses send.
const waDigits = String(c.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const wa = text => waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent(text)}` : '';
const cancelHref = wa(`I want to cancel my appointment. Reference: ${c.ref}`);
const link = a => `${c.PUBLIC_BASE}/webhook/booking-action?ref=${encodeURIComponent(c.ref)}`
  + `&token=${encodeURIComponent(c.token)}&action=${a}`;

const html = `
<div style="font-family:Helvetica,Arial,sans-serif;max-width:560px;margin:0 auto;color:#123F52">
  <div style="background:#0E7490;color:#fff;padding:22px 24px;border-radius:14px 14px 0 0">
    <div style="font-size:19px;font-weight:bold">${c.CLINIC_NAME}</div>
    <div style="font-size:13px;opacity:.9;margin-top:3px">One step left to confirm your appointment</div>
  </div>
  <div style="border:1px solid #CDE9F1;border-top:0;border-radius:0 0 14px 14px;padding:24px;background:#fff">
    <p style="margin:0 0 16px">Hello <strong>${esc(c.name)}</strong>,</p>
    <p style="margin:0 0 18px">We are holding this slot for you. Please confirm within
       <strong>${c.holdMinutes} minutes</strong> or it will be offered to another patient.</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:22px">
      <tr><td style="padding:9px 0;color:#4A6572">Treatment</td><td style="text-align:right;font-weight:bold">${c.serviceName}</td></tr>
      ${c.doctorName ? `<tr><td style="padding:9px 0;color:#4A6572;border-top:1px solid #EDF5F8">Dentist</td><td style="text-align:right;font-weight:bold;border-top:1px solid #EDF5F8">${esc(c.doctorName)}</td></tr>` : ''}
      <tr><td style="padding:9px 0;color:#4A6572;border-top:1px solid #EDF5F8">Date</td><td style="text-align:right;font-weight:bold;border-top:1px solid #EDF5F8">${c.prettyDate}</td></tr>
      <tr><td style="padding:9px 0;color:#4A6572;border-top:1px solid #EDF5F8">Time</td><td style="text-align:right;font-weight:bold;border-top:1px solid #EDF5F8">${c.prettyTime}</td></tr>
      <tr><td style="padding:9px 0;color:#4A6572;border-top:1px solid #EDF5F8">Duration</td><td style="text-align:right;font-weight:bold;border-top:1px solid #EDF5F8">${c.durationMin} minutes</td></tr>
      <tr><td style="padding:9px 0;color:#4A6572;border-top:1px solid #EDF5F8">Reference</td><td style="text-align:right;font-weight:bold;border-top:1px solid #EDF5F8">${c.ref}</td></tr>
    </table>
    <a href="${link('confirm')}" style="display:block;text-align:center;background:#047857;color:#fff;
       text-decoration:none;padding:15px;border-radius:12px;font-weight:bold;font-size:16px">
       Confirm my appointment</a>
    <a href="${cancelHref || link('cancel')}" style="display:block;text-align:center;color:#4A6572;text-decoration:none;
       padding:13px;margin-top:9px;font-size:14px">I can no longer make it &mdash; cancel${cancelHref ? ' on WhatsApp' : ''}</a>
    <p style="font-size:12px;color:#4A6572;margin:22px 0 0;border-top:1px solid #EDF5F8;padding-top:16px">
      Prefer to reply? Just reply to this email with the word <strong>CONFIRM</strong> and keep
      <strong>[Ref: ${c.ref}]</strong> in the subject line.</p>
  </div>
</div>`;

return [{ json: { ...c, eventId: ev.id, html,
  subject: `Confirm your appointment — ${c.prettyDate}, ${c.prettyTime}  [Ref: ${c.ref}]` } }];

// ===== DentalFlow availability rules =========================================
// The SAME code sits in workflow 01 (which times to offer) and workflow 02
// (re-check at the moment of booking), so the two can never disagree.
//
// Doctors tab:  doctor_id | name | calendar_id | services | email | active
//   services:   comma-separated service ids, or blank / "all"
// Hours tab:    day | open | close | break_start | break_end | closed | doctor
//   A doctor with ANY rows of their own uses only those rows: a day with no
//   row is a day off. A doctor with no rows uses the clinic rows (doctor blank).
// Nobody active in the Doctors tab: one doctor on the clinic calendar, exactly
// as before multi-doctor support. (The tab itself must exist: run the sheet
// upgrade before importing these workflows.)
const DF = (() => {
  const clean = v => String(v ?? '').trim();
  // "14:00", "14:00:00", "14.00" and "2:00 PM" all mean the same time; a sheet may show any of them.
  const toMin = t => {
    const m = /^(\d{1,2})[:.](\d{2})(?::\d{2})?\s*([ap])?\.?m?\.?$/i.exec(clean(t));
    if (!m) return NaN;
    let h = Number(m[1]); const ap = (m[3] || '').toLowerCase();
    if (ap === 'p' && h < 12) h += 12;
    if (ap === 'a' && h === 12) h = 0;
    return h * 60 + Number(m[2]);
  };
  const toHHMM = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  const truthy = v => clean(v).toUpperCase() === 'TRUE';
  const parts = (isoStr, tz) => {
    const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit',
      day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
    const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
    return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
  };
  const dayName = (date, tz) => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'long' })
    .format(new Date(date + 'T12:00:00Z')).toLowerCase();

  function settings(rows) { const s = {}; for (const r of rows || []) s[clean(r[0])] = r[1]; return s; }

  function services(rows) {
    return (rows || []).map(r => ({ id: clean(r[0]), name: clean(r[1]), min: Number(r[2]), price: Number(r[3]),
      active: r[4] === undefined || clean(r[4]).toUpperCase() !== 'FALSE' })).filter(s => s.id);
  }

  function doctors(rows, fallbackCalendar, fallbackName) {
    const list = (rows || []).map(r => ({
      id: clean(r[0]).toLowerCase(), name: clean(r[1]) || clean(r[0]), calendarId: clean(r[2]),
      services: clean(r[3]), email: clean(r[4]),
      active: r[5] === undefined || clean(r[5]).toUpperCase() !== 'FALSE'
    })).filter(d => d.id && d.calendarId && d.active);
    if (list.length) return list;
    return [{ id: 'clinic', name: fallbackName || 'the dentist', calendarId: fallbackCalendar || 'primary',
              services: 'all', email: '', active: true, implicit: true }];
  }

  const doesService = (d, svcId) => {
    const s = d.services.toLowerCase();
    return !s || s === 'all' || s.split(/[\s,;]+/).filter(Boolean).includes(String(svcId).toLowerCase());
  };

  // wanted: a doctor id, or '' / 'any' for every doctor who does this treatment
  function eligible(docs, svcId, wanted) {
    const w = clean(wanted).toLowerCase();
    const any = !w || w === 'any';
    return docs.filter(d => doesService(d, svcId) && (any || d.id === w));
  }

  function hoursFor(hoursRows, doctorId, dow) {
    const rows = hoursRows || [];
    const own = rows.filter(r => clean(r[6]).toLowerCase() === doctorId);
    const pool = own.length ? own : rows.filter(r => !clean(r[6]));
    const r = pool.find(x => clean(x[0]).toLowerCase() === dow);
    if (!r || truthy(r[5])) return null;                          // no row or closed = not working
    const open = toMin(r[1] || '10:00'), close = toMin(r[2] || '20:00');
    if (!(close > open)) return null;
    const bs = toMin(r[3]), be = toMin(r[4]);
    return { open, close, brk: bs < be ? [bs, be] : null };
  }

  // Busy blocks for one calendar on one day, in minutes. A calendar Google
  // could not read is treated as fully busy: an unreadable diary must never
  // look empty, or that doctor would be double-booked.
  // Google may answer for "primary" under the account's email address instead.
  // `asked` is every calendar id we asked about: one answer under a key we did
  // not ask for can only be that calendar.
  function busyFor(fb, calId, day, tz, asked) {
    const cal = (fb && fb.calendars) || {};
    let entry = cal[calId];
    if (!entry) {
      const keys = Object.keys(cal);
      const spare = asked ? keys.filter(k => !asked.includes(k)) : keys;
      if (spare.length === 1 && (asked || keys.length === 1)) entry = cal[spare[0]];
    }
    if (!entry || (entry.errors && entry.errors.length)) return { ok: false, blocks: [[0, 1440]] };
    const blocks = [];
    for (const b of entry.busy || []) {
      const s = parts(b.start, tz), e = parts(b.end, tz);
      if (e.date < day || s.date > day) continue;
      blocks.push([s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min]);
    }
    return { ok: true, blocks };
  }

  // Does an appointment of `dur` minutes at `start` fit this doctor's day?
  function fits(start, dur, buffer, h, blocks) {
    if (!h || !(start >= h.open) || start + dur > h.close) return false;
    const all = h.brk ? blocks.concat([h.brk]) : blocks;
    return !all.some(([bs, be]) => start < be && (start + dur + buffer) > bs);
  }

  function freeTimes({ dur, buffer, gran, earliest, h, blocks }) {
    const out = [];
    if (!h) return out;
    for (let t = h.open; t + dur <= h.close; t += gran) {
      if (t < earliest) continue;
      if (fits(t, dur, buffer, h, blocks)) out.push(toHHMM(t));
    }
    return out;
  }

  const busyMinutes = blocks => blocks.reduce((n, [a, b]) => n + Math.max(0, b - a), 0);

  return { clean, toMin, toHHMM, parts, dayName, settings, services, doctors, doesService,
