// Which calendars to re-check: the doctor the patient chose, or for "any",
// every active doctor who does this treatment.
const v  = $('Validate Request').first().json;
const vr = $input.first().json.valueRanges || [];
const rows = i => (vr[i] && vr[i].values) || [];   // 0 Services 1 Hours 2 Settings 3 Holidays 4 Doctors
const set  = DF.settings(rows(2));
const docs = DF.doctors(rows(4), v.CALENDAR_ID, set.clinic_name || v.CLINIC_NAME);
const eligible = DF.eligible(docs, v.service, v.doctor);
return [{ json: { eligible,
  // Google needs at least one calendar; with nobody eligible the booking is refused anyway.
  freeBusyItems: (eligible.length ? eligible : [{ calendarId: v.CALENDAR_ID }]).map(d => ({ id: d.calendarId })) } }];

/* LAST LINE OF DEFENCE AGAINST DOUBLE-BOOKING
   Two patients can pass the re-check for the same dentist and time within the
   same second, before either hold exists. So, after creating our hold, we list
   that dentist's events for the slot. If another live event overlaps it, the
   hold created LATER withdraws (ties broken by event id). Both requests run the
   same rule, so exactly one booking survives and the other patient is told the
   time has just gone. */
const ours = $('Create PENDING Hold').first().json || {};
const items = (($input.first().json || {}).items) || [];
const t = s => Date.parse(s || '');
const s0 = t(ours.start && ours.start.dateTime), e0 = t(ours.end && ours.end.dateTime);
const rank = ev => [t(ev.created) || 0, String(ev.id || '')];
const before = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1]);
const clash = items.some(ev => {
  if (!ev || ev.id === ours.id || ev.status === 'cancelled' || ev.transparency === 'transparent') return false;
  const s1 = t(ev.start && (ev.start.dateTime || ev.start.date)), e1 = t(ev.end && (ev.end.dateTime || ev.end.date));
  if (!(s1 < e0 && e1 > s0)) return false;                 // no overlap
  return before(rank(ev), rank(ours));                     // the other one was there first: we yield
});
return [{ json: { clash, eventId: ours.id, calendarId: $('Check Availability').first().json.calendarId } }];
